import { expect, test, uniqueName } from "../../fixtures";

const DAY_MS = 24 * 60 * 60 * 1000;

function isoDateInDays(days: number): string {
  const now = new Date();
  const todayUtc = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return new Date(todayUtc + days * DAY_MS).toISOString().slice(0, 10);
}

function insuranceCertificate(expiry: string): Buffer {
  const text = [
    "CERTIFICATE OF INSURANCE",
    "Insurer: Contoso Mutual Insurance Co.",
    "Policy Number: POL-REV08-0001",
    "Effective Date: 2024-01-01",
    `Expiration Date: ${expiry}`,
  ].join("\n");
  return Buffer.from(text, "utf-8");
}

const cases: Array<{ days: number; include: boolean }> = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("insurance expiring soon flag", () => {
  for (const { days, include } of cases) {
    const verb = include ? "include" : "do not include";

    test(
      `vendor whose insurance expires in ${days} days should ${verb} insurance_expiring_soon`,
      { tag: "@REV-08" },
      async ({ apiAs }) => {
        // Arrange
        const member = await apiAs("member");
        const createResponse = await member.post("/api/vendors", {
          data: {
            name: uniqueName(`REV08 Insurance ${days}d`),
            category: "services",
            contact_email: `rev08-${days}-${Date.now().toString(36)}${Math.random()
              .toString(36)
              .slice(2, 6)}@example.test`,
          },
        });
        expect(createResponse.status()).toBe(201);
        const vendor = await createResponse.json();

        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "insurance-certificate.txt",
              mimeType: "text/plain",
              buffer: insuranceCertificate(isoDateInDays(days)),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);

        // Act + Assert
        await expect(async () => {
          const response = await member.get(`/api/vendors/${vendor.id}`);
          expect(response.status()).toBe(200);
          const body = await response.json();
          expect(Array.isArray(body.flags)).toBe(true);
          if (include) {
            expect(body.flags).toContain("insurance_expiring_soon");
          } else {
            expect(body.flags).not.toContain("insurance_expiring_soon");
          }
        }).toPass({ timeout: 30_000, intervals: [500, 1_000, 2_000] });
      },
    );
  }
});
